import React, { useState, useEffect, useRef } from 'react';
import Background from '../components/Background';
import MeshSphere from '../components/MeshSphere';

const PHASES = [
  { name:'Andas in',  seconds:4, label:'Djupt in — fyll lungorna', mood:'calm', speed:0.25, distort:0.08 },
  { name:'Håll',      seconds:7, label:'Håll — var stilla',        mood:'default', speed:0.10, distort:0.05 },
  { name:'Andas ut',  seconds:8, label:'Sakta ut — släpp taget',   mood:'flow', speed:0.20, distort:0.08 },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(()=>{
      c--; setCount(c);
      if (c<=0){ clearInterval(timer.current); const np=(pi+1)%3; setTimeout(()=>runPhase(np,np===0?ci+1:ci),400); }
    },1000);
  };
  const start = ()=>{ setRunning(true); setDone(false); runPhase(0,0); };
  useEffect(()=>()=>clearInterval(timer.current),[]);
  const cur = PHASES[phase];

  if (done) return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 22px', position:'relative' }}>
      <Background mood="flow" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={220} speed={0.7} distort={0.18} />
        </div>
        <h2 style={{ fontSize:34, fontWeight:700, letterSpacing:'-0.04em', color:'#1c1917', marginBottom:10 }}>Bra jobbat 🌿</h2>
        <p style={{ fontSize:15, color:'rgba(28,25,23,0.5)', marginBottom:36, fontWeight:300, maxWidth:260, margin:'0 auto 36px' }}>Ditt nervsystem har lugnat ner sig. Alla 4 omgångar klara.</p>
        <div style={{ display:'flex', gap:10, justifyContent:'center' }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'13px 24px', borderRadius:100, background:'#1c1917', color:'#f0ece6', fontSize:13, fontWeight:600, boxShadow:'0 4px 20px rgba(0,0,0,0.18)', border:'none' }}>Checka in humöret</button>
          <button onClick={()=>{setDone(false);setRunning(false);}} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(255,255,255,0.65)', border:'1px solid rgba(255,255,255,0.85)', color:'rgba(28,25,23,0.65)', fontSize:13, backdropFilter:'blur(12px)' }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', paddingBottom:96, display:'flex', flexDirection:'column', position:'relative' }}>
      <Background mood={running ? cur.mood : 'default'} />

      {/* Spiral label — rotated on the left side */}
      <div style={{ position:'fixed', left:20, top:'50%', transform:'translateY(-50%) rotate(-90deg)', transformOrigin:'center center', zIndex:10, pointerEvents:'none' }}>
        <span style={{ fontSize:11, fontWeight:700, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(28,25,23,0.2)' }}>Spiral</span>
      </div>

      <div style={{ flex:1, display:'flex', flexDirection:'column', position:'relative', zIndex:1 }}>

        {/* Phase guide — centered, top of screen */}
        <div style={{ textAlign:'center', padding:'28px 22px 0' }}>
          <p style={{ fontSize:11, color:'rgba(28,25,23,0.35)', fontWeight:500, textTransform:'uppercase', letterSpacing:'0.1em', marginBottom:16 }}>
            4 – 7 – 8 andningsövning
          </p>
          <div style={{ display:'flex', gap:28, justifyContent:'center' }}>
            {PHASES.map((p, i) => (
              <div key={i} style={{ textAlign:'center', transition:'all .5s' }}>
                <div style={{ fontSize:22, fontWeight:700, letterSpacing:'-0.03em', lineHeight:1, color: running&&phase===i ? '#1c1917' : 'rgba(28,25,23,0.18)', transition:'color .5s' }}>{p.seconds}</div>
                <div style={{ fontSize:9, fontWeight:500, textTransform:'uppercase', letterSpacing:'0.08em', marginTop:3, color: running&&phase===i ? 'rgba(28,25,23,0.5)' : 'rgba(28,25,23,0.15)', transition:'color .5s' }}>{p.name}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Orb — fills most of screen, counter inside */}
        <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center' }}>
          <div style={{ position:'relative',
            transition: running
              ? phase===0 ? `transform ${PHASES[0].seconds}s linear`
              : phase===1 ? 'transform 0.8s ease-out'
              : `transform ${PHASES[2].seconds}s linear`
              : 'transform 1.4s cubic-bezier(0.16,1,0.3,1)',
            transform: running
              ? phase===0 ? 'scale(1.32)'
              : phase===1 ? 'scale(1.34)'
              : 'scale(0.78)'
              : 'scale(1)',
          }}>
            <MeshSphere size={320} speed={running ? cur.speed : 0.3} distort={running ? cur.distort : 0.45} />

            {/* Counter inside orb */}
            {running && (
              <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', pointerEvents:'none' }}>
                <div style={{ fontSize:10, fontWeight:600, textTransform:'uppercase', letterSpacing:'0.12em', color:'rgba(28,25,23,0.4)', marginBottom:4 }}>{cur.name}</div>
                <div style={{ fontSize:58, fontWeight:700, color:'rgba(28,25,23,0.75)', lineHeight:1, letterSpacing:'-0.05em' }}>{count}</div>
                <div style={{ fontSize:10, color:'rgba(28,25,23,0.28)', marginTop:6, letterSpacing:'0.06em' }}>{cycle+1} / {TOTAL}</div>
              </div>
            )}
          </div>
        </div>

        {/* Bottom */}
        <div style={{ padding:'0 22px 16px' }}>
          {running ? (
            <div style={{ background:'rgba(255,255,255,0.65)', borderRadius:18, padding:'13px 18px', textAlign:'center', backdropFilter:'blur(16px)', border:'1px solid rgba(255,255,255,0.85)' }}>
              <p style={{ fontSize:14, color:'rgba(28,25,23,0.55)', fontWeight:300 }}>{cur.label}</p>
            </div>
          ) : (
            <>
              <h1 style={{ fontSize:'clamp(28px,7vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#1c1917', marginBottom:10, lineHeight:1.05 }}>
                Andningsövning<br/><span style={{ fontStyle:'italic', fontWeight:300, color:'rgba(28,25,23,0.38)' }}>4 minuter</span>
              </h1>
              <p style={{ fontSize:14, color:'rgba(28,25,23,0.48)', fontWeight:300, lineHeight:1.75, marginBottom:20 }}>
                Aktiverar det parasympatiska nervsystemet och minskar stresshormoner.
              </p>
              <button onClick={start} style={{ width:'100%', padding:'15px', borderRadius:100, background:'#1c1917', color:'#f0ece6', fontSize:14, fontWeight:600, border:'none', boxShadow:'0 4px 20px rgba(0,0,0,0.18)' }}>
                Starta →
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
